  async function requestContent(){const authHeaders:Record<string,string>=token?{authorization:`Bearer ${token}`}:{ },fresh=Date.now();const[news,photos,ads]=await Promise.all([fetch(`/api/v1/feed?language=${language}&limit=50&_=${fresh}`,{headers:authHeaders,cache:"no-store"}).then(r=>{if(!r.ok)throw new Error("Could not load stories");return r.json()}),fetch(`/api/v1/galleries?language=${language}&_=${fresh}`,{headers:authHeaders,cache:"no-store"}).then(r=>{if(!r.ok)throw new Error("Could not load galleries");return r.json()}),fetch(`/api/v1/placements?language=${language}&category=${view==="latest"?"all":selectedCategory}&_=${fresh}`,{cache:"no-store"}).then(r=>r.ok?r.json():{items:[]})]);const nextStories:Story[]=(news.items??[]).map((item:Story)=>({...item,kind:"story"})),nextGalleries:Gallery[]=(photos.items??[]).map((item:Gallery&{images:string|GalleryImage[]})=>({...item,kind:"gallery",images:typeof item.images==="string"?JSON.parse(item.images):item.images}));setSponsored((ads.items??[]).map((item:Sponsored)=>({...item,kind:"sponsored"})));return{nextStories,nextGalleries}}
  async function loadContent(showLoading=true){if(showLoading)setLoading(true);try{const{nextStories,nextGalleries}=await requestContent();setStories(nextStories);setGalleries(nextGalleries);currentContentIdsRef.current=new Set([...nextStories,...nextGalleries].map(contentKey));currentBreakingIdsRef.current=new Set(nextStories.filter(story=>story.breaking).map(story=>`${story.id}:${story.updatedAt}`));currentImportantIdsRef.current=new Set(nextStories.filter(story=>story.important).map(story=>`${story.id}:${story.updatedAt}`));setSeenBaseline([...seenContentRef.current]);setNewContentAvailable(false);return true}catch(error){notify((error as Error).message||"Could not refresh the news");return false}finally{if(showLoading)setLoading(false)}}
  async function refreshNewContent(){if(refreshingContent)return;const targetKey=newContentTargetRef.current;setRefreshingContent(true);const refreshed=await loadContent(false);if(refreshed){setView("feed");setSelectedCategory("all");setQuery("");setFeedRenderKey(key=>key+1);setTimeout(()=>{const target=[...document.querySelectorAll<HTMLElement>(".story-card[data-content-key]")].find(card=>card.dataset.contentKey===targetKey),feed=document.querySelector<HTMLElement>(".story-feed");if(target&&feed){target.scrollIntoView({behavior:"smooth",block:"start"});seenContentRef.current.add(targetKey!)}else feed?.scrollTo({top:0,behavior:"smooth"});newContentTargetRef.current=null},80)}setRefreshingContent(false)}
