  useEffect(()=>{let active=true;getSupabaseClient().then(async client=>{if(!client||!active)return;setSession((await client.auth.getSession()).data.session);client.auth.onAuthStateChange((_e,s)=>setSession(s))});fetch("/api/v1/categories").then(r=>r.json()).then(d=>setCategories(d.items??[]));return()=>{active=false}},[]);
  useEffect(()=>{const savedLanguage=localStorage.getItem("kurufeetha-language"),savedTextSize=localStorage.getItem("kurufeetha-text-size");if(savedTextSize==="large"||savedTextSize==="xlarge")setReaderTextSize(savedTextSize);if(savedLanguage==="en"||savedLanguage==="dv")setLanguage(savedLanguage);try{seenContentRef.current=new Set(JSON.parse(localStorage.getItem("kurufeetha-seen-content")||"[]"))}catch{seenContentRef.current=new Set()}setLanguageReady(true)},[]);
  useEffect(()=>{if(languageReady)localStorage.setItem("kurufeetha-language",language)},[language,languageReady]);
