  useEffect(()=>{const applyPreferences=(event:Event)=>{const detail=(event as CustomEvent<{textSize?:TextSize;notifyBreaking?:boolean;notifyImportant?:boolean;displayName?:string}>).detail;if(detail.textSize)setReaderTextSize(detail.textSize);setProfile(current=>current?{...current,...(typeof detail.notifyBreaking==="boolean"?{notifyBreaking:detail.notifyBreaking}:{}),...(typeof detail.notifyImportant==="boolean"?{notifyImportant:detail.notifyImportant}:{}),...(detail.displayName?{displayName:detail.displayName}:{})}:current)};window.addEventListener("kurufeetha-preferences",applyPreferences);return()=>window.removeEventListener("kurufeetha-preferences",applyPreferences)},[]);
