  useEffect(()=>{if(!window.matchMedia("(max-width: 760px)").matches)return;requestAnimationFrame(()=>document.querySelector<HTMLElement>(".story-feed")?.scrollTo({top:0,behavior:"auto"}))},[view]);
  useEffect(()=>{if(!token){setProfile(null);return}fetch("/api/v1/me",{headers:{authorization:`Bearer ${token}`}}).then(r=>r.json()).then(d=>{if(d.user){setProfile(d.user);setFollows(d.followedCategoryIds??[]);const savedLanguage=localStorage.getItem("kurufeetha-language");if(savedLanguage!=="en"&&savedLanguage!=="dv")setLanguage(d.user.preferredLanguage);if(!d.user.onboardingCompletedAt)setAccountOpen(true)}})},[token]);
  useEffect(()=>{if(token){fetch("/api/v1/me/bookmarks",{headers:{authorization:`Bearer ${token}`}}).then(r=>r.json()).then(d=>setSaved((d.items??[]).map((item:{cardId:string})=>item.cardId)));return}try{setSaved(JSON.parse(localStorage.getItem("kurufeetha-bookmarks")||"[]"))}catch{setSaved([])}},[token]);
  useEffect(()=>{if(token){fetch("/api/v1/me/likes",{headers:{authorization:`Bearer ${token}`}}).then(r=>r.json()).then(d=>setLikes((d.items??[]).map((item:{contentType:string;contentId:string})=>`${item.contentType}:${item.contentId}`)));return}try{setLikes(JSON.parse(localStorage.getItem("kurufeetha-likes")||"[]"))}catch{setLikes([])}},[token]);
  useEffect(()=>{if(languageReady)loadContent()},[language,languageReady,token,selectedCategory,view]);
  useEffect(()=>{if(!languageReady)return;let active=true;async function check(){try{const{nextStories,nextGalleries}=await requestContent();if(!active)return;const breakingEnabled=profile?.notifyBreaking??true,importantEnabled=profile?.notifyImportant??false;const breaking=breakingEnabled?nextStories.filter(story=>story.breaking&&!currentBreakingIdsRef.current.has(`${story.id}:${story.updatedAt}`)).sort((a,b)=>b.updatedAt-a.updatedAt)[0]:undefined;const important=!breaking&&importantEnabled?nextStories.filter(story=>story.important&&!currentImportantIdsRef.current.has(`${story.id}:${story.updatedAt}`)).sort((a,b)=>b.updatedAt-a.updatedAt)[0]:undefined;if(breaking)setBreakingAlert(breaking);else if(important)setImportantAlert(important);const newItems=[...nextStories,...nextGalleries].filter(item=>!currentContentIdsRef.current.has(contentKey(item))).sort((a,b)=>b.publishedAt-a.publishedAt);if(newItems.length&&!breaking&&!important){newContentTargetRef.current=contentKey(newItems[0]);setNewContentAvailable(true)}}catch{}}const timer=setInterval(check,15_000),onVisibility=()=>{if(document.visibilityState==="visible")check()};document.addEventListener("visibilitychange",onVisibility);return()=>{active=false;clearInterval(timer);document.removeEventListener("visibilitychange",onVisibility)}},[language,languageReady,token,profile?.notifyBreaking,profile?.notifyImportant,selectedCategory,view]);
  async function shareStory(story:Story){const url=story.articleUrl?`${location.origin}${story.articleUrl}`:location.href,data={title:story.headline,text:story.summary,url};try{if(navigator.share){await navigator.share(data);return}}catch{return}await navigator.clipboard?.writeText(url);notify(rtl?"ލިންކް ކޮޕީ ކުރެވިއްޖެ":"Link copied")}
  async function toggleBookmark(cardId:string){const next=!saved.includes(cardId);if(token){const r=await fetch("/api/v1/me/bookmarks",{method:"PUT",headers:{"content-type":"application/json",authorization:`Bearer ${token}`},body:JSON.stringify({cardId,saved:next})});if(!r.ok)return notify(rtl?"ސޭވް ނުކުރެވުނު":"Could not save story")}const updated=next?[...saved,cardId]:saved.filter(id=>id!==cardId);setSaved(updated);if(!token)localStorage.setItem("kurufeetha-bookmarks",JSON.stringify(updated));notify(next?(rtl?"ސޭވް ކުރެވިއްޖެ":"Story saved"):(rtl?"ސޭވް ފިލާއިން ނައްތާލެވިއްޖެ":"Removed from saved"))}
