  const visible=useMemo(()=>{const categoryLikes=new Map<string,number>(),seenAtLoad=new Set(seenBaseline);for(const item of [...stories,...galleries])if(likes.includes(`${item.kind}:${item.id}`))categoryLikes.set(item.category,(categoryLikes.get(item.category)||0)+1);const score=(item:Story|Gallery)=>(item.kind==="story"&&item.breaking?2000:0)+(seenAtLoad.has(contentKey(item))?0:1000)+(item.kind==="story"&&item.followed?100:0)+(item.affinity??0)*10+(categoryLikes.get(item.category)||0)*12;const organic=[...stories,...(view==="feed"||view==="latest"?galleries:[])].filter(item=>item.kind==="story"?(view!=="saved"||saved.includes(item.id))&&(view!=="feed"||selectedCategory==="all"||item.category===selectedCategory)&&`${item.headline} ${item.summary} ${item.categoryName}`.toLowerCase().includes(query.toLowerCase()):(view==="feed"||view==="latest")&&(view!=="feed"||selectedCategory==="all"||item.category===selectedCategory)&&`${item.topic} ${item.categoryName}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>view==="saved"||view==="latest"?b.publishedAt-a.publishedAt:freshnessGroup(b,timeNow)-freshnessGroup(a,timeNow)||score(b)-score(a)||randomizedCardOrder(a.id,feedSeed)-randomizedCardOrder(b.id,feedSeed));if((view!=="feed"&&view!=="latest")||query)return organic;const mixed:Array<Story|Gallery|Sponsored>=[],deliveryCounts=new Map<string,number>();organic.forEach((item,index)=>{mixed.push(item);if((index+1)%7!==0||!sponsored.length)return;const campaign=sponsored[Math.floor(index/7)%sponsored.length],count=deliveryCounts.get(campaign.campaignId)||0,limit=Math.min(2,campaign.frequencyCap||2);if(count<limit){mixed.push(campaign);deliveryCounts.set(campaign.campaignId,count+1)}});return mixed},[stories,galleries,sponsored,feedSeed,likes,query,seenBaseline,selectedCategory,saved,view,timeNow]);
  useEffect(()=>{const feed=document.querySelector(".story-feed");if(!feed||typeof IntersectionObserver==="undefined")return;const observer=new IntersectionObserver(entries=>{let changed=false;for(const entry of entries){if(!entry.isIntersecting||entry.intersectionRatio<.65)continue;const el=entry.target as HTMLElement,campaignId=el.dataset.campaignId;if(campaignId){const visitor=anonymousId(),key=`${campaignId}:${visitor}:${Math.floor(Date.now()/3_600_000)}:impression`;fetch("/api/v1/placements/events",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({campaignId,anonymousId:visitor,eventKey:key,type:"impression",language,placement:"feed"})});continue}const key=el.dataset.contentKey;if(key&&!seenContentRef.current.has(key)){seenContentRef.current.add(key);changed=true;const[type,id]=key.split(":");fetch("/api/v1/analytics/events",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({anonymousId:anonymousId(),eventKey:`${anonymousId()}:${key}:view`,contentType:type,contentId:id,type:"view",language})})}}if(changed){const recent=[...seenContentRef.current].slice(-1000);seenContentRef.current=new Set(recent);localStorage.setItem("kurufeetha-seen-content",JSON.stringify(recent))}},{root:feed,threshold:.65});feed.querySelectorAll(".story-card[data-content-key],.story-card[data-campaign-id]").forEach(card=>observer.observe(card));return()=>observer.disconnect()},[visible,view,language]);
